
const D=window.EXPLORER_DATA;
const app=document.getElementById('app'), modalRoot=document.getElementById('modalRoot');
const LS='animalExplorerStateV1';
const blankState=()=>({ratings:{},conditions:{},prep:{},savedCareers:[],savedPrograms:[],compareCareers:[],comparePrograms:[],snapshots:[],careerReactions:{},notes:{},progression:{career:'',education:'bachelor',experience:'0-2'}});
let state=load(); let exploreStep=0;
function load(){try{return {...blankState(),...JSON.parse(localStorage.getItem(LS)||'{}')}}catch(e){return blankState()}}
function save(){localStorage.setItem(LS,JSON.stringify(state));}
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const money=n=>n?('$'+Math.round(n/1000)+'K'):'—';
const careerByName=n=>D.careers.find(c=>c.name===n), progByCode=c=>D.programs.find(p=>p.code===c);
function route(){const r=(location.hash||'#home').slice(1).split('?')[0]; document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===r)); render(r)}
function go(r){location.hash=r}
window.addEventListener('hashchange',route);
document.getElementById('menuBtn').onclick=()=>document.getElementById('nav').classList.toggle('open');
document.querySelectorAll('[data-route]').forEach(a=>a.onclick=()=>document.getElementById('nav').classList.remove('open'));
document.getElementById('guideLink').href=D.resources.guide;document.getElementById('workbookLink').href=D.resources.workbook;document.getElementById('sheetLink').href=D.resources.spreadsheet;

function themeScores(){let sum=Array(10).fill(0), wt=Array(10).fill(0), unknown=Array(10).fill(0);
  const groups=[...D.topics,...D.activities,...D.relationships,...D.scienceQuestions];
  groups.forEach(q=>{const v=state.ratings[q.id]; q.dims.forEach(di=>{if(v==='?')unknown[di]++; else if(v!==undefined){sum[di]+=Number(v);wt[di]++;}})});
  return sum.map((v,i)=>({i,label:D.dimLabels[i],score:wt[i]?v/(wt[i]*3):0,known:wt[i],unknown:unknown[i]}));}
function topThemes(n=4){return themeScores().filter(x=>x.known).sort((a,b)=>b.score-a.score).slice(0,n)}
function affinity(dims){const ts=themeScores();let num=0,den=0,reasons=[];dims.forEach((d,i)=>{if(ts[i].known){num+=d*ts[i].score;den+=d;if(ts[i].score>.66&&d>=2)reasons.push(D.dimLabels[i])}});return {score:den?num/den:0,reasons:reasons.slice(0,3)}}
function recommendedCareers(limit=8){return D.careers.filter(c=>!(c.details['Market status']||'').startsWith('EDU')).map(c=>({...c,_a:affinity(c.dims)})).sort((a,b)=>b._a.score-a._a.score).slice(0,limit)}
function recommendedPrograms(limit=5){return D.programs.map(p=>({...p,_a:affinity(p.dims)})).sort((a,b)=>b._a.score-a._a.score).slice(0,limit)}
function toggle(arr,key){const i=arr.indexOf(key);if(i>=0)arr.splice(i,1);else arr.push(key);save();}
function supportGroup(c,code){return Object.entries(c.support).filter(([k,v])=>v===code).map(([k])=>k)}
function supportStrength(code){return code==='S'||code==='SG'?3:code==='C'||code==='C*'?2:code==='G'?1:0}
function programCareerCoverage(p,savedOnly=false){const set=savedOnly?state.savedCareers:D.careers.map(c=>c.name);let n=0;set.forEach(name=>{const c=careerByName(name); if(c&&supportStrength(c.support[p.code])>=2)n++});return n}

function evidenceLabel(c){return D.evidenceStatusLabels?.[c.evidenceStatus]||String(c.evidenceStatus||'Evidence available').replaceAll('_',' ')}
function evidenceClass(c){return c.evidenceStatus==='verified_current_market'?'market':c.evidenceStatus?.startsWith('verified')?'verified':'established'}
function roleKindLabel(c){return D.roleKindLabels?.[c.roleKind]||String(c.roleKind||'career').replaceAll('_',' ')}
function currentPostingCount(c){return (c.recentPostings||[]).length}
function observedTitleCount(c){return (c.observedTitles||[]).length}
function postingSalaryText(c){const m=c.observedMarketSalary;if(!m)return null;return `${money(m.observedMin)}–${money(m.observedMax)} (${m.count} posting${m.count===1?'':'s'})`}
function sourceLink(src,label){return src?.url?`<a href="${esc(src.url)}" target="_blank" rel="noopener">${esc(label||src.organization||src.title)} ↗</a>`:esc(label||'Source')}
function uniqueObservedTitles(c){const seen=new Set();return (c.observedTitles||[]).filter(x=>{const k=(x.title||'').toLowerCase();if(!k||seen.has(k))return false;seen.add(k);return true})}
function explicitEdgesFor(name){return (D.careerEdges||[]).filter(e=>e.fromCareer===name)}

function meaningfulSupport(c,programCode){return supportStrength(c.support[programCode])>=2}
function careerSupportedBySavedPath(c){return state.savedPrograms.some(code=>meaningfulSupport(c,code))}
function programSupportsSavedCareer(p){return state.savedCareers.some(name=>{const c=careerByName(name);return c&&meaningfulSupport(c,p.code)})}

const PROGRAM_FEATURES=['Behavior & cognition','Animal care & welfare','Wildlife & field ecology','Conservation & ecology','Physiology & biological mechanisms','Research-intensive','Quantitative / GIS / telemetry','Zoo / aquarium','Experiential / internship','Broad biological science'];
function programFeatureTags(p){const d=p.dims||[],raw=(p.experienceTags||[]).map(x=>x.toLowerCase()),out=[];
  if((d[0]||0)>=2.4)out.push('Behavior & cognition');
  if((d[1]||0)>=2.0||(d[2]||0)>=2.0)out.push('Animal care & welfare');
  if((d[3]||0)>=2.0)out.push('Wildlife & field ecology');
  if((d[6]||0)>=2.0)out.push('Conservation & ecology');
  if((d[5]||0)>=2.3)out.push('Physiology & biological mechanisms');
  if((d[8]||0)>=2.6)out.push('Research-intensive');
  if((d[7]||0)>=2.3||raw.includes('gis')||raw.includes('telemetry'))out.push('Quantitative / GIS / telemetry');
  if(raw.includes('zoo'))out.push('Zoo / aquarium');
  if(raw.includes('internship')||raw.includes('fieldwork')||raw.includes('animal care'))out.push('Experiential / internship');
  if((p.type||'').toLowerCase().includes('broad'))out.push('Broad biological science');
  return out;
}

function eduRankFromCareer(c){const b=(c.educationBand||'').toLowerCase(),t=(c.details?.['Typical education / progression']||'').toLowerCase();
  if(b.includes('graduate study pathway'))return 9;
  if(b.includes('graduate degree typical'))return (t.includes('ph.d')||t.includes('doctor'))?3:2;
  if(t.includes('ph.d')||t.includes('doctor'))return 3;
  if(t.includes('m.s.')||t.includes('master'))return 2;
  return 1;
}
function selectedEducationRank(v){return v==='doctorate'?3:v==='masters'?2:v==='bachelor'?1:0}
function experienceRank(v){return v==='10+'?3:v==='5-10'?2:v==='2-5'?1:0}
function careerStage(c){const n=c.name.toLowerCase(),b=(c.educationBand||'').toLowerCase();
  if(b.includes('graduate study pathway'))return 9;
  if(b.includes('experience-driven / later career'))return 4;
  if(/curator|manager|principal investigator|university professor/.test(n))return 4;
  if(/technician|assistant|zookeeper|keeper|caretaker|caregiver|trainer|aquarist|educator|naturalist|rehabilitator|field ecologist|science writer/.test(n))return 1;
  if(/specialist/.test(n))return 2;
  if(/coordinator|scientist|biologist|ecologist|zoologist|mammalogist|ornithologist|herpetologist|physiologist|neuroethologist|consultant|research coordinator/.test(n))return 3;
  return 2;
}
function tagOverlap(a,b){const A=new Set(a||[]),B=new Set(b||[]),u=new Set([...A,...B]);if(!u.size)return 0;let i=0;A.forEach(x=>{if(B.has(x))i++});return i/u.size}
function careerSimilarity(a,b){let sq=0;for(let i=0;i<10;i++)sq+=((a.dims?.[i]||0)-(b.dims?.[i]||0))**2;const dim=Math.max(0,1-Math.sqrt(sq)/9.5),tag=tagOverlap(a.workTags,b.workTags),cat=a.category===b.category?1:0;return .56*dim+.29*tag+.15*cat}
function midPoint(c){return c.midSalary?.length?(c.midSalary[0]+c.midSalary[1])/2:0}
function progressionReason(from,to,eduRank,kind){const shared=(from.workTags||[]).filter(x=>(to.workTags||[]).includes(x)).slice(0,3);const needs=eduRankFromCareer(to)>eduRank;let txt=shared.length?`Shared work in ${shared.join(', ')}.`:'Related animal/science skill profile.';if(kind==='natural')txt+=' The role builds on a similar work family with greater responsibility or specialization.';if(kind==='growth')txt+=needs?' Additional formal education would commonly be part of the move.':' The move is plausible but usually requires added specialization, responsibility, or targeted experience.';if(kind==='lateral')txt+=' It uses overlapping skills at a broadly comparable career level, but changes the emphasis or setting.';return txt}
function inferredProgressionOptions(current,eduRank,expRank){const cs=careerStage(current),cm=midPoint(current),maxNaturalDelta=expRank>=2?2:1;const pool=D.careers.filter(c=>c.name!==current.name&&eduRankFromCareer(c)<9).map(c=>({c,sim:careerSimilarity(current,c),stage:careerStage(c),edu:eduRankFromCareer(c),mid:midPoint(c),inferred:true}));const natural=pool.filter(x=>x.sim>=.54&&x.stage>cs&&x.stage-cs<=maxNaturalDelta&&x.edu<=eduRank&&(x.stage<4||expRank>=2)).sort((a,b)=>b.sim-a.sim||b.mid-a.mid).slice(0,7);const naturalNames=new Set(natural.map(x=>x.c.name));const growth=pool.filter(x=>!naturalNames.has(x.c.name)&&x.sim>=.48&&x.stage>cs&&((x.edu>eduRank)||(x.stage-cs>maxNaturalDelta)||(x.stage>=4&&expRank<2)||(x.mid&&cm&&x.mid>cm*1.08))).sort((a,b)=>b.sim-a.sim).slice(0,8);const used=new Set([...naturalNames,...growth.map(x=>x.c.name)]);const lateral=pool.filter(x=>!used.has(x.c.name)&&x.sim>=.50&&Math.abs(x.stage-cs)<=1&&x.edu<=Math.max(eduRank,1)&&(x.c.category!==current.category||tagOverlap(current.workTags,x.c.workTags)>=.45)).sort((a,b)=>b.sim-a.sim).slice(0,8);return {natural,growth,lateral}}
function explicitProgressionOptions(current){const natural=[],growth=[],lateral=[];for(const e of explicitEdgesFor(current.name)){const c=careerByName(e.toCareer);if(!c)continue;const o={c,sim:careerSimilarity(current,c),edge:e,inferred:false};if(e.relationship_type==='lateral'||e.relationship_type==='professional_assignment')lateral.push(o);else if(e.relationship_type==='natural_growth'||(e.relationship_type==='specialization'&&e.typicality==='common')||(e.relationship_type==='management'&&e.typicality==='common'))natural.push(o);else growth.push(o)}return {natural,growth,lateral}}
function progressionOptions(current,eduRank,expRank){const explicit=explicitProgressionOptions(current),inf=inferredProgressionOptions(current,eduRank,expRank),explicitNames=new Set([...explicit.natural,...explicit.growth,...explicit.lateral].map(x=>x.c.name));inf.natural=inf.natural.filter(x=>!explicitNames.has(x.c.name));inf.growth=inf.growth.filter(x=>!explicitNames.has(x.c.name));inf.lateral=inf.lateral.filter(x=>!explicitNames.has(x.c.name));const merge=(a,b,limit)=>[...a,...b].slice(0,limit);const natural=merge(explicit.natural,inf.natural,8),used=new Set(natural.map(x=>x.c.name));const growth=merge(explicit.growth.filter(x=>!used.has(x.c.name)),inf.growth.filter(x=>!used.has(x.c.name)),9);growth.forEach(x=>used.add(x.c.name));const lateral=merge(explicit.lateral.filter(x=>!used.has(x.c.name)),inf.lateral.filter(x=>!used.has(x.c.name)),9);return {natural,growth,lateral}}

function render(r){document.getElementById('nav').classList.remove('open'); if(r==='explore')return renderExplore();if(r==='careers')return renderCareers();if(r==='progression')return renderProgression();if(r==='evidence')return renderEvidence();if(r==='programs')return renderPrograms();if(r==='dashboard')return renderDashboard();if(r==='glossary')return renderGlossary();renderHome()}

function renderHome(){const tops=topThemes();app.innerHTML=`<div class="page"><section class="hero"><div><div class="eyebrow">Explore • Learn • Test • Revise</div><h1>Find the animal & science paths worth exploring.</h1><p>This is not a career test or a closed list of jobs. Explore a growing, evidence-backed map of animal and wildlife career families, real employer titles, college preparation, and questions worth testing through experience.</p><div class="actions"><button class="btn primary" onclick="go('explore')">Start guided exploration</button><button class="btn" onclick="go('careers')">Browse careers</button><button class="btn" onclick="go('progression')">Explore career progression</button><button class="btn" onclick="go('evidence')">Market & evidence</button><button class="btn" onclick="go('programs')">Browse college paths</button></div></div><div class="hero-card"><h3>${tops.length?'What your exploration is showing':'Nothing is locked in'}</h3>${tops.length?tops.map(t=>`<div class="theme-row"><small>${esc(t.label)}</small><div class="bar"><span style="width:${Math.round(t.score*100)}%"></span></div></div>`).join(''):`<p>Rate only what you can judge. “Not sure” becomes an exploration target rather than a missing answer.</p><ul><li>Explore broad interests first</li><li>Learn what careers really involve</li><li>Work backward to college preparation</li><li>Save snapshots as thinking changes</li></ul>`}</div></section>
<section class="grid cols-3"><div class="card feature-card" onclick="go('explore')"><div class="iconbox">◎</div><div class="kicker">Guided</div><h3>Build a pattern gradually</h3><p>Rate topics, activities, scientific questions, working conditions and preparation independently. No forced either/or choices.</p></div><div class="card feature-card" onclick="go('careers')"><div class="iconbox">⌕</div><div class="kicker">Open exploration</div><h3>Filter and drill down</h3><p>Browse the full career landscape by category, animal contact, work type, education, outlook and college-path support.</p></div><div class="card feature-card" onclick="go('progression')"><div class="iconbox">↗</div><div class="kicker">Progression</div><h3>See where a role can lead</h3><p>Start from a current or hypothetical career and explore natural growth, further-growth, and lateral options at different education and experience levels.</p></div><div class="card feature-card" onclick="go('evidence')"><div class="iconbox">✓</div><div class="kicker">Evidence</div><h3>See the real market behind the map</h3><p>Inspect observed job titles, current/recent postings, qualification standards, credentials, sources and what still needs more research.</p></div><div class="card feature-card" onclick="go('dashboard')"><div class="iconbox">↻</div><div class="kicker">Living record</div><h3>Keep uncertainty visible</h3><p>Save careers, college paths and snapshots. Turn “not sure” answers into experiences that can actually resolve them.</p></div></section>
<section class="home-summary"><div class="section-title"><div><h2>Career landscape</h2><p>Seven broad families from the companion guide. They overlap; the categories are starting points rather than boxes.</p></div></div><div class="card">${Object.entries(D.categorySummaries).map(([k,v])=>`<div class="category-row"><b>${esc(k)}</b><span>${esc(v.short)}</span><span class="subtle">${esc(v.progression)}</span></div>`).join('')}</div></section></div>`}

const ratingLabels=[['0','Not appealing'],['1','A little'],['2','Moderately'],['3','Very'],['?','Not sure yet']];
function ratingQuestions(items){return `<div class="question-list">${items.map(q=>`<div class="question"><div class="question-head"><div><h4>${esc(q.label)}</h4>${q.help?`<div class="help">${esc(q.help)}</div>`:''}</div></div><div class="ratings">${ratingLabels.map(([v,l])=>`<button class="rating ${v==='?'?'unknown':''} ${state.ratings[q.id]===v?'selected':''}" data-q="${q.id}" data-v="${v}">${l}</button>`).join('')}</div></div>`).join('')}</div>`}
function conditionQuestions(){const labs=['Hard no','Concern','Tolerable','Potentially enjoyable'];return `<div class="question-list">${D.conditions.map(q=>`<div class="question"><h4>${esc(q.label)}</h4><div class="ratings">${labs.map((l,i)=>`<button class="rating ${state.conditions[q.id]===i?'selected':''}" data-cond="${q.id}" data-v="${i}">${l}</button>`).join('')}</div></div>`).join('')}</div>`}
function prepQuestions(){const labs=['Sounds fine','Worth it for right career','Not sure','Probably not'];return `<div class="question-list">${D.prepPaths.map(q=>`<div class="question"><h4>${esc(q.label)}</h4><div class="help">${esc(q.help)}</div><div class="ratings">${labs.map((l,i)=>`<button class="rating ${state.prep[q.id]===i?'selected':''}" data-prep="${q.id}" data-v="${i}">${l}</button>`).join('')}</div></div>`).join('')}</div>`}
function themePanel(){const ts=themeScores().filter(x=>x.known||x.unknown).sort((a,b)=>b.score-a.score);return `<div class="card sticky-panel"><div class="kicker">What we're noticing</div><h3 style="margin-top:4px">Current themes</h3>${ts.length?ts.slice(0,7).map(t=>`<div class="theme-row"><small>${esc(t.label)}${t.unknown?` <span title="${t.unknown} unsure answer(s)">?</span>`:''}</small><div class="bar"><span style="width:${Math.round(t.score*100)}%"></span></div></div>`).join(''):`<p class="subtle">Themes will appear as ratings are added.</p>`}<div class="actions"><button class="btn small soft" onclick="go('dashboard')">See current snapshot</button></div></div>`}
function renderExplore(){const steps=[['Interests',D.topics,'What subjects and problems naturally pull your attention?'],['Activities',D.activities,'What kinds of actual work sound satisfying?'],['Animals & settings',D.relationships,'What kinds of relationships to animals appeal?'],['Scientific questions',D.scienceQuestions,'Which questions would be interesting enough to pursue deeply?'],['Work realities',null,'What conditions are acceptable, concerning, or potentially enjoyable?'],['Preparation',null,'Which education and early-career paths could be acceptable for the right work?']];
 const [name,items,desc]=steps[exploreStep];app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">Guided exploration</div><h1>${exploreStep+1}. ${name}</h1><p>${desc||''} Rate independently. There is no need to force a preference between two things that may both be appealing—or neither.</p></div></div><div class="stepper">${steps.map((s,i)=>`<button class="step ${i===exploreStep?'active':i<exploreStep?'done':''}" data-step="${i}">${i+1}. ${s[0]}</button>`).join('')}</div><div class="explore-layout"><div>${exploreStep<4?ratingQuestions(items):exploreStep===4?conditionQuestions():prepQuestions()}<div class="actions"><button class="btn" id="prevStep" ${exploreStep===0?'disabled':''}>← Back</button>${exploreStep<5?`<button class="btn primary" id="nextStep">Next →</button>`:`<button class="btn primary" onclick="go('dashboard')">See what this suggests</button>`}</div></div>${themePanel()}</div></div>`;
 document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{state.ratings[b.dataset.q]=b.dataset.v;save();renderExplore()});document.querySelectorAll('[data-cond]').forEach(b=>b.onclick=()=>{state.conditions[b.dataset.cond]=Number(b.dataset.v);save();renderExplore()});document.querySelectorAll('[data-prep]').forEach(b=>b.onclick=()=>{state.prep[b.dataset.prep]=Number(b.dataset.v);save();renderExplore()});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{exploreStep=Number(b.dataset.step);renderExplore()}); const p=document.getElementById('prevStep');if(p)p.onclick=()=>{exploreStep=Math.max(0,exploreStep-1);renderExplore()};const n=document.getElementById('nextStep');if(n)n.onclick=()=>{exploreStep=Math.min(5,exploreStep+1);renderExplore()}}

function careerCard(c,rec=false){const d=c.details||{}, entry=c.entrySalary?`${money(c.entrySalary[0])}–${money(c.entrySalary[1])}`:'—', mid=c.midSalary?`${money(c.midSalary[0])}–${money(c.midSalary[1])}`:'—',observedPay=postingSalaryText(c);return `<div class="card career-card"><button class="save-btn ${state.savedCareers.includes(c.name)?'saved':''}" title="Save" onclick="event.stopPropagation();toggle(state.savedCareers,'${esc(c.name).replace(/'/g,"\\'")}');renderCareers()">★</button><div class="kicker">${esc(c.domain?.name||c.category)} • ${esc(c.roleFamily?.name||'')}</div><h3 class="card-title">${esc(c.name)}</h3><div class="tagrow"><span class="tag evidence ${evidenceClass(c)}">${esc(evidenceLabel(c))}</span><span class="tag">${esc(roleKindLabel(c))}</span>${currentPostingCount(c)?`<span class="tag green">${currentPostingCount(c)} recent posting${currentPostingCount(c)===1?'':'s'}</span>`:''}</div><p>${esc(c.roleFocus||d['Typical education / progression']||'')}</p><div class="tagrow">${c.workTags.slice(0,5).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="tag green">${esc(c.directContact)} animal contact</span></div><div class="meta"><div><small>Education</small><b>${esc(c.educationBand)}</b></div><div><small>Market titles observed</small><b>${observedTitleCount(c)||'—'}</b></div><div><small>${observedPay?'Observed posting pay':'Broad mid proxy'}</small><b>${observedPay||mid}</b></div></div>${rec&&c._a?.reasons?.length?`<div class="notice"><b>Why it is showing:</b> ${c._a.reasons.map(esc).join(', ')}</div>`:''}<div class="actions"><button class="btn small primary" onclick="openCareer('${esc(c.name).replace(/'/g,"\\'")}')">Explore role & evidence</button><button class="btn small" onclick="toggleCompareCareer('${esc(c.name).replace(/'/g,"\\'")}')">Compare</button></div></div>`}

function renderCareers(){app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">93 canonical roles • 32 role families</div><h1>Career Explorer</h1><p>These roles organize a much larger market of employer-specific titles and specializations. Browse by domain or role family, then open any role to see observed titles and current/recent evidence.</p></div><div class="actions"><button class="btn soft" id="recToggle">Show what matches me</button><button class="btn" onclick="go('progression')">Career progression →</button><button class="btn" onclick="go('evidence')">How the evidence works</button></div></div><div class="split"><aside class="card filters" id="careerFilters"></aside><section><div class="resultbar"><span id="careerCount"></span><select id="careerSort"><option value="name">Sort: A–Z</option><option value="match">Sort: current match</option><option value="evidence">Sort: market evidence</option><option value="salary">Sort: pay evidence</option></select></div><div class="grid cols-2" id="careerResults"></div></section></div></div><div id="compareCareerDrawer"></div>`;buildCareerFilters();updateCareerResults();document.getElementById('careerSort').onchange=updateCareerResults;document.getElementById('recToggle').onclick=e=>{e.target.classList.toggle('primary');e.target.dataset.on=e.target.dataset.on==='1'?'0':'1';updateCareerResults()}}
function buildCareerFilters(){const cats=[...new Set(D.careers.map(c=>c.category))];const tags=[...new Set(D.careers.flatMap(c=>c.workTags))].sort();const domains=D.domains||[];document.getElementById('careerFilters').innerHTML=`<div class="filter-section"><label class="head">Search all titles & evidence</label><input id="careerSearch" class="searchbox" placeholder="Career, observed title, employer, skill…"></div><div class="filter-section"><label class="head">Saved / linked</label><label class="check"><input type="checkbox" id="savedCareerOnly"> Show saved careers only</label><label class="check"><input type="checkbox" id="savedPathCareerOnly"> Only careers supported by a saved college path</label><div class="help">${state.savedPrograms.length?`${state.savedPrograms.length} saved path${state.savedPrograms.length===1?'':'s'} available for linking.`:'Save one or more college paths to use the second filter.'}</div></div><div class="filter-section"><label class="head">Domain</label><select id="domainFilter"><option value="">All domains</option>${domains.map(d=>`<option value="${d.domain_id}">${esc(d.name)} (${d.roleCount})</option>`).join('')}</select></div><div class="filter-section"><label class="head">Role family</label><select id="familyFilter"><option value="">All role families</option>${D.roleFamilies.map(f=>`<option value="${f.family_id}" data-domain="${f.domain_id}">${esc(f.name)} (${f.role_count})</option>`).join('')}</select></div><div class="filter-section"><label class="head">Market evidence</label><label class="check"><input type="checkbox" id="postingOnly"> Has current/recent posting evidence</label><select id="evidenceFilter"><option value="">Any evidence status</option>${Object.entries(D.evidenceStatusLabels||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Role type</label><select id="roleKindFilter"><option value="">Any type</option>${Object.entries(D.roleKindLabels||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Direct animal contact</label><select id="contactFilter"><option value="">Any</option><option>High</option><option>Moderate</option><option>Low / variable</option></select></div><div class="filter-section"><label class="head">Education path</label><select id="eduFilter"><option value="">Any</option>${[...new Set(D.careers.map(c=>c.educationBand))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Kinds of work</label>${tags.map(t=>`<label class="check"><input type="checkbox" class="workTag" value="${esc(t)}"> ${esc(t)}</label>`).join('')}</div><div class="filter-section"><label class="head">Supported strongly by one specific college path</label><select id="pathFilter"><option value="">Any path</option>${D.programs.map(p=>`<option value="${p.code}">${p.code} — ${esc(p.title)}</option>`).join('')}</select></div><button class="btn small" id="clearCareer">Clear filters</button>`;['careerSearch','domainFilter','familyFilter','evidenceFilter','roleKindFilter','contactFilter','eduFilter','pathFilter','savedCareerOnly','savedPathCareerOnly','postingOnly'].forEach(id=>document.getElementById(id).addEventListener('input',updateCareerResults));document.querySelectorAll('.workTag').forEach(x=>x.onchange=updateCareerResults);document.getElementById('domainFilter').addEventListener('change',e=>{const fam=document.getElementById('familyFilter');if(fam.value&&fam.selectedOptions[0]?.dataset.domain!==e.target.value)fam.value='';updateCareerResults()});document.getElementById('clearCareer').onclick=()=>{document.querySelectorAll('#careerFilters input').forEach(x=>{if(x.type==='checkbox')x.checked=false;else x.value=''});document.querySelectorAll('#careerFilters select').forEach(x=>x.value='');updateCareerResults()}}
function updateCareerResults(){let arr=D.careers.map(c=>({...c,_a:affinity(c.dims)}));const q=(document.getElementById('careerSearch')?.value||'').toLowerCase(),domain=document.getElementById('domainFilter')?.value||'',family=document.getElementById('familyFilter')?.value||'',evidence=document.getElementById('evidenceFilter')?.value||'',kind=document.getElementById('roleKindFilter')?.value||'',contact=document.getElementById('contactFilter')?.value||'',edu=document.getElementById('eduFilter')?.value||'',path=document.getElementById('pathFilter')?.value||'',work=[...document.querySelectorAll('.workTag:checked')].map(x=>x.value), rec=document.getElementById('recToggle')?.dataset.on==='1',savedOnly=document.getElementById('savedCareerOnly')?.checked||false,linkedOnly=document.getElementById('savedPathCareerOnly')?.checked||false,postingOnly=document.getElementById('postingOnly')?.checked||false;arr=arr.filter(c=>{const market=[...(c.aliases||[]),...(c.observedTitles||[]).map(x=>x.title),...(c.recentPostings||[]).flatMap(x=>[x.title,x.employer,x.location])].join(' ');const blob=(c.name+' '+c.roleFocus+' '+c.roleFamily?.name+' '+Object.values(c.details||{}).join(' ')+' '+c.workTags.join(' ')+' '+market+' '+(c.competencies||[]).map(x=>x.name).join(' ')).toLowerCase();return (!q||blob.includes(q))&&(!domain||c.domain?.id===domain)&&(!family||c.roleFamily?.id===family)&&(!evidence||c.evidenceStatus===evidence)&&(!kind||c.roleKind===kind)&&(!contact||c.directContact===contact)&&(!edu||c.educationBand===edu)&&(!path||['S','SG'].includes(c.support[path]))&&work.every(t=>c.workTags.includes(t))&&(!rec||c._a.score>.47)&&(!savedOnly||state.savedCareers.includes(c.name))&&(!linkedOnly||careerSupportedBySavedPath(c))&&(!postingOnly||currentPostingCount(c)>0)});const sort=document.getElementById('careerSort')?.value||'name';if(sort==='match')arr.sort((a,b)=>b._a.score-a._a.score);else if(sort==='evidence')arr.sort((a,b)=>currentPostingCount(b)-currentPostingCount(a)||observedTitleCount(b)-observedTitleCount(a)||a.name.localeCompare(b.name));else if(sort==='salary')arr.sort((a,b)=>((b.observedMarketSalary?.medianHigh||b.midSalary?.[0]||0)-(a.observedMarketSalary?.medianHigh||a.midSalary?.[0]||0)));else arr.sort((a,b)=>a.name.localeCompare(b.name));document.getElementById('careerCount').textContent=`${arr.length} of ${D.dataSummary.canonicalRoles} canonical roles`;document.getElementById('careerResults').innerHTML=arr.map(c=>careerCard(c,rec||sort==='match')).join('')||`<div class="empty">No roles match these filters.${linkedOnly&&!state.savedPrograms.length?' Save a college path first, or turn off the saved-path restriction.':' Remove one or more filters.'}</div>`;renderCareerCompareDrawer()}
function toggleCompareCareer(n){toggle(state.compareCareers,n);if(state.compareCareers.length>4)state.compareCareers.shift();save();renderCareerCompareDrawer()}
function renderCareerCompareDrawer(){const root=document.getElementById('compareCareerDrawer');if(!root)return;root.innerHTML=state.compareCareers.length?`<div class="compare-drawer"><b>${state.compareCareers.length} selected</b><button class="btn small" onclick="openCareerCompare()">Compare careers</button><button class="btn small ghost" onclick="state.compareCareers=[];save();renderCareerCompareDrawer()">Clear</button></div>`:''}

function programCard(p,rec=false){const savedMatches=programCareerCoverage(p,true);return `<div class="card program-card"><button class="save-btn ${state.savedPrograms.includes(p.code)?'saved':''}" onclick="event.stopPropagation();toggle(state.savedPrograms,'${p.code}');renderPrograms()">★</button><div class="kicker">${esc(p.school)} • ${esc(p.type)}</div><h3 class="card-title">${p.code}: ${esc(p.title)}</h3><p>${esc(p.fundamental)}</p><div class="tagrow">${p.experienceTags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${savedMatches?`<div class="notice"><b>${savedMatches}</b> saved career${savedMatches===1?'':'s'} supported directly or credibly.</div>`:''}${rec&&p._a?.reasons?.length?`<div class="notice" style="margin-top:8px"><b>Current-interest match:</b> ${p._a.reasons.map(esc).join(', ')}</div>`:''}<div class="actions"><button class="btn small primary" onclick="openProgram('${p.code}')">Explore path</button><button class="btn small" onclick="toggleCompareProgram('${p.code}')">Compare</button></div></div>`}
function renderPrograms(){const schools=[...new Set(D.programs.map(p=>p.school))];app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">Ten academic paths • four universities</div><h1>College Path Explorer</h1><p>Use broad academic and experiential features that cut across multiple paths, then drill into courses, research, four-year progression and career coverage.</p></div><button class="btn soft" id="progRec">Show what matches me</button></div><div class="split"><aside class="card filters"><div class="filter-section"><label class="head">Search</label><input id="progSearch" class="searchbox" placeholder="Behavior, GIS, zoo, physiology…"></div><div class="filter-section"><label class="head">Saved / linked</label><label class="check"><input type="checkbox" id="savedProgramOnly"> Show saved paths only</label><label class="check"><input type="checkbox" id="savedCareerRestrict"> Only paths that support a saved career</label><div class="help">${state.savedCareers.length?`${state.savedCareers.length} saved career${state.savedCareers.length===1?'':'s'} available for linking.`:'Save one or more careers to use the second filter.'}</div></div><div class="filter-section"><label class="head">School</label><select id="schoolFilter"><option value="">All schools</option>${schools.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Academic / experience features</label><div class="chipbar" id="progFeatures">${PROGRAM_FEATURES.map(x=>`<button class="chip" data-pfeature="${esc(x)}">${esc(x)}</button>`).join('')}</div><label class="check" style="margin-top:10px"><input type="radio" name="featureMode" value="any" checked> Match any selected feature</label><label class="check"><input type="radio" name="featureMode" value="all"> Match all selected features</label></div><div class="filter-section"><label class="head">Sort by saved careers</label><div class="help">Use “saved-career coverage” in the sort menu to rank all remaining paths by how many saved careers they support.</div></div><button class="btn small" id="clearProg">Clear filters</button></aside><section><div class="resultbar"><span id="progCount"></span><select id="progSort"><option value="school">Sort: school</option><option value="match">Sort: current match</option><option value="coverage">Sort: saved-career coverage</option></select></div><div class="grid cols-2" id="progResults"></div></section></div></div><div id="compareProgDrawer"></div>`;['progSearch','schoolFilter','savedProgramOnly','savedCareerRestrict','progSort'].forEach(id=>document.getElementById(id).addEventListener('input',updatePrograms));document.querySelectorAll('[data-pfeature]').forEach(x=>x.onclick=()=>{x.classList.toggle('active');updatePrograms()});document.querySelectorAll('[name="featureMode"]').forEach(x=>x.onchange=updatePrograms);document.getElementById('progRec').onclick=e=>{e.target.dataset.on=e.target.dataset.on==='1'?'0':'1';e.target.classList.toggle('primary');updatePrograms()};document.getElementById('clearProg').onclick=()=>{document.getElementById('progSearch').value='';document.getElementById('schoolFilter').value='';document.getElementById('savedProgramOnly').checked=false;document.getElementById('savedCareerRestrict').checked=false;document.querySelector('[name="featureMode"][value="any"]').checked=true;document.querySelectorAll('[data-pfeature]').forEach(x=>x.classList.remove('active'));updatePrograms()};updatePrograms()}
function updatePrograms(){let arr=D.programs.map(p=>({...p,_a:affinity(p.dims),_cov:programCareerCoverage(p,true),_features:programFeatureTags(p)}));const q=(document.getElementById('progSearch')?.value||'').toLowerCase(),school=document.getElementById('schoolFilter')?.value||'',features=[...document.querySelectorAll('[data-pfeature].active')].map(x=>x.dataset.pfeature),mode=document.querySelector('[name="featureMode"]:checked')?.value||'any',rec=document.getElementById('progRec')?.dataset.on==='1',savedOnly=document.getElementById('savedProgramOnly')?.checked||false,linkedOnly=document.getElementById('savedCareerRestrict')?.checked||false;arr=arr.filter(p=>{const blob=(p.title+' '+p.fundamental+' '+p.scienceFoundation.join(' ')+' '+p.animalContent.join(' ')+' '+p.experience+' '+p.research).toLowerCase();const featureOK=!features.length||(mode==='all'?features.every(t=>p._features.includes(t)):features.some(t=>p._features.includes(t)));return (!q||blob.includes(q))&&(!school||p.school===school)&&featureOK&&(!rec||p._a.score>.5)&&(!savedOnly||state.savedPrograms.includes(p.code))&&(!linkedOnly||programSupportsSavedCareer(p))});let sort=document.getElementById('progSort')?.value||'school';if(sort==='match')arr.sort((a,b)=>b._a.score-a._a.score);else if(sort==='coverage')arr.sort((a,b)=>b._cov-a._cov||b._a.score-a._a.score);else arr.sort((a,b)=>a.school.localeCompare(b.school)||a.code.localeCompare(b.code));document.getElementById('progCount').textContent=`${arr.length} academic paths`;document.getElementById('progResults').innerHTML=arr.map(p=>programCard(p,rec||sort==='match')).join('')||`<div class="empty">No college paths match these filters.${linkedOnly&&!state.savedCareers.length?' Save a career first, or turn off the saved-career restriction.':' Try fewer selected features or switch from “all” to “any.”'}</div>`;renderProgCompareDrawer()}
function toggleCompareProgram(c){toggle(state.comparePrograms,c);if(state.comparePrograms.length>4)state.comparePrograms.shift();save();renderProgCompareDrawer()}
function renderProgCompareDrawer(){const r=document.getElementById('compareProgDrawer');if(!r)return;r.innerHTML=state.comparePrograms.length?`<div class="compare-drawer"><b>${state.comparePrograms.length} selected</b><button class="btn small" onclick="openProgramCompare()">Compare paths</button><button class="btn small ghost" onclick="state.comparePrograms=[];save();renderProgCompareDrawer()">Clear</button></div>`:''}


function groupedCareerOptions(selected=''){const cats=[...new Set(D.careers.filter(c=>eduRankFromCareer(c)<9).map(c=>c.category))];return `<option value="">Select a current or hypothetical career…</option>${cats.map(cat=>`<optgroup label="${esc(cat)}">${D.careers.filter(c=>c.category===cat&&eduRankFromCareer(c)<9).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${esc(c.name)}" ${c.name===selected?'selected':''}>${esc(c.name)}</option>`).join('')}</optgroup>`).join('')}`}
function progressionCard(o,kind,eduRank){const c=o.c,d=c.details||{},mid=c.midSalary?`${money(c.midSalary[0])}–${money(c.midSalary[1])}`:'—',needs=eduRankFromCareer(c)>eduRank,e=o.edge;const why=e?`${e.notes||''}${e.education_change&&e.education_change!=='none'?` Education change: ${e.education_change}.`:''}${e.experience_change?` Experience: ${e.experience_change}.`:''}`:progressionReason(careerByName(state.progression.career),c,eduRank,kind);return `<div class="progression-card"><div class="kicker">${kind==='natural'?'Natural growth':kind==='growth'?'Possible growth':'Lateral option'}</div><h3>${esc(c.name)}</h3><p>${esc(c.roleFocus)}</p><div class="tagrow"><span class="tag ${e?'green':'gold'}">${e?`Explicit ${esc(e.evidence_status)} edge`:'Inferred nearby option'}</span><span class="tag ${needs?'gold':'green'}">${needs?'Additional education likely':'Fits assumed education'}</span></div><div class="meta"><div><small>Education</small><b>${esc(c.educationBand)}</b></div><div><small>Market evidence</small><b>${currentPostingCount(c)} postings</b></div><div><small>Similarity</small><b>${Math.round(o.sim*100)}%</b></div></div><p class="progression-why">${esc(why)}</p>${e?.source?`<div class="source-mini">${sourceLink(e.source,e.source.organization)}</div>`:''}<div class="actions"><button class="btn small primary" onclick="openCareer('${esc(c.name).replace(/'/g,"\\'")}')">Explore career</button><button class="btn small" onclick="state.progression.career='${esc(c.name).replace(/'/g,"\\'")}';save();renderProgression()">Continue from here</button></div></div>`}
function renderProgression(){state.progression=state.progression||{career:'',education:'bachelor',experience:'0-2'};const cur=careerByName(state.progression.career),edu=selectedEducationRank(state.progression.education),exp=experienceRank(state.progression.experience);let result='';if(cur){const opts=progressionOptions(cur,edu,exp);const sec=(title,desc,items,kind)=>`<section class="progression-section"><div class="section-title"><div><h2>${title}</h2><p>${desc}</p></div></div>${items.length?`<div class="grid cols-3">${items.map(o=>progressionCard(o,kind,edu)).join('')}</div>`:`<div class="empty">No strong ${title.toLowerCase()} matches emerged from the current combination. Try a different education or experience assumption, or use lateral options.</div>`}</section>`;result=`<div class="card progression-current"><div><div class="kicker">Starting point</div><h2>${esc(cur.name)}</h2><p>${esc(cur.roleFocus)}</p></div><button class="btn small" onclick="openCareer('${esc(cur.name).replace(/'/g,"\\'")}')">Open full career profile</button></div>${sec('Natural growth','Roles using much of the same skill base at greater responsibility or specialization, and broadly plausible with the education and experience assumed here.',opts.natural,'natural')}${sec('Possible growth','Related upward moves that may require more specialization, more experience, or additional formal education.',opts.growth,'growth')}${sec('Lateral options','Comparable-level roles that use overlapping skills but shift the setting, problem, or emphasis.',opts.lateral,'lateral')}`}
 app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">Career progression</div><h1>Where could this role lead?</h1><p>Choose a current—or hypothetical future—career, then vary education and experience. The results distinguish natural growth, broader growth possibilities, and lateral moves. Explicit researched transitions appear first; similarity-based options fill gaps and are clearly labeled as inferred.</p></div></div><div class="card progression-controls"><div><label><b>Current or starting career</b><select id="progCareerSelect">${groupedCareerOptions(state.progression.career)}</select></label></div><div><label><b>Education completed / assumed</b><select id="progEducation"><option value="some" ${state.progression.education==='some'?'selected':''}>High school / some college</option><option value="bachelor" ${state.progression.education==='bachelor'?'selected':''}>Bachelor’s degree</option><option value="masters" ${state.progression.education==='masters'?'selected':''}>Master’s degree</option><option value="doctorate" ${state.progression.education==='doctorate'?'selected':''}>Doctorate</option></select></label></div><div><label><b>Relevant experience at that point</b><select id="progExperience"><option value="0-2" ${state.progression.experience==='0-2'?'selected':''}>0–2 years</option><option value="2-5" ${state.progression.experience==='2-5'?'selected':''}>2–5 years</option><option value="5-10" ${state.progression.experience==='5-10'?'selected':''}>5–10 years</option><option value="10+" ${state.progression.experience==='10+'?'selected':''}>10+ years</option></select></label></div></div><div class="notice" style="margin:14px 0 24px">Use this as an exploration map, not a promotion schedule. Green “explicit edge” labels come from curated progression relationships; gold “inferred” labels are similarity-based possibilities that still need stronger market validation.</div>${cur?result:`<div class="empty"><h3>Choose a career to start</h3><p>You can begin with a saved career or select any role in the career database.</p>${state.savedCareers.length?`<div class="chipbar" style="justify-content:center;margin-top:12px">${state.savedCareers.map(n=>`<button class="chip" onclick="state.progression.career='${esc(n).replace(/'/g,"\\'")}';save();renderProgression()">${esc(n)}</button>`).join('')}</div>`:''}</div>`}</div>`;
 ['progCareerSelect','progEducation','progExperience'].forEach(id=>document.getElementById(id)?.addEventListener('change',e=>{if(id==='progCareerSelect')state.progression.career=e.target.value;if(id==='progEducation')state.progression.education=e.target.value;if(id==='progExperience')state.progression.experience=e.target.value;save();renderProgression()}));
}

function openCareer(name){const c=careerByName(name),d=c.details||{};const groups=[['Strong/direct paths',['S','SG']],['Credible with planning',['C','C*']],['Graduate-oriented foundations',['G']],['Weakly aligned',['N']]];const quick=['More direct animal contact','More research','More fieldwork','Less graduate school','More conservation','More behavior'];const titles=uniqueObservedTitles(c).slice(0,14),posts=(c.recentPostings||[]).slice(0,8),pay=postingSalaryText(c);modalRoot.innerHTML=`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="kicker">${esc(c.domain?.name||c.category)} • ${esc(c.roleFamily?.name||'')}</div><h2>${esc(c.name)}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="tagrow"><span class="tag evidence ${evidenceClass(c)}">${esc(evidenceLabel(c))}</span><span class="tag">${esc(roleKindLabel(c))}</span><span class="tag">Last verified ${esc(c.lastVerified||D.dataSummary.asOf)}</span></div><p style="font-size:18px">${esc(c.roleFocus)}</p><div class="notice"><b>This is a canonical exploration role, not a limit on job titles.</b> Employers may use many different titles for related work. The market examples below show titles actually observed in this research snapshot; their absence does not mean other titles or employers do not exist.</div>${titles.length?`<h3>Observed real-world titles</h3><div class="observed-grid">${titles.map(x=>`<div class="observed-title"><b>${esc(x.title)}</b><span>${esc(x.organization||'')} ${x.location?`• ${esc(x.location)}`:''}</span>${x.source?`<small>${sourceLink(x.source,x.source.organization)}</small>`:''}</div>`).join('')}</div>`:''}${posts.length?`<h3>Current / recent market examples</h3><div class="posting-list">${posts.map(x=>`<div class="posting"><div><b>${esc(x.title)}</b><span>${esc(x.employer)}${x.location?` • ${esc(x.location)}`:''}${x.posted_date?` • ${esc(x.posted_date)}`:''}</span></div><div class="posting-right">${x.salary_min!=null?`<b>${x.salary_unit==='hourly'?'$'+x.salary_min.toFixed(2)+'/hr':money(x.salary_min)+'–'+money(x.salary_max||x.salary_min)}</b>`:''}<a href="${esc(x.url)}" target="_blank" rel="noopener">posting ↗</a></div></div>`).join('')}</div>`:''}<div class="detail-grid evidence-summary"><div class="detail"><h4>Education / progression</h4><p>${esc(c.educationBand)}</p></div><div class="detail"><h4>Market evidence</h4><p>${observedTitleCount(c)} observed title${observedTitleCount(c)===1?'':'s'}; ${currentPostingCount(c)} current/recent posting${currentPostingCount(c)===1?'':'s'}.</p></div><div class="detail"><h4>Observed posting pay</h4><p>${pay||'Not enough posting-level salary observations yet.'}</p></div><div class="detail"><h4>Broad occupation proxy</h4><p>${c.midSalary?`Mid proxy ${money(c.midSalary[0])}–${money(c.midSalary[1])}.`:esc(d['Salary context']||'No dedicated O*NET/BLS occupation; use market and related-science evidence.')}</p></div></div>${c.competencies?.length?`<h3>Competencies that matter</h3><div class="chipbar">${c.competencies.map(x=>`<span class="chip static" title="${esc(x.description)}">${esc(x.name)}</span>`).join('')}</div>`:''}${c.qualificationProfiles?.length?`<h3>Formal qualification rules</h3>${c.qualificationProfiles.map(q=>`<div class="detail qualification"><h4>${esc(q.organization)}${q.series_code?` — ${esc(q.series_code)}`:''}</h4><p>${esc(q.education_requirement||'')} ${esc(q.coursework_requirement||'')} ${esc(q.experience_requirement||'')}</p><small><a href="${esc(q.source_url)}" target="_blank" rel="noopener">official requirement ↗</a></small></div>`).join('')}`:''}${c.credentials?.length?`<h3>Credentials / permits</h3>${c.credentials.map(x=>`<div class="detail qualification"><h4>${esc(x.name)} <span class="tag">${esc(x.relationship)}</span></h4><p>${esc(x.description||x.notes||'')}</p>${x.source_url?`<small><a href="${esc(x.source_url)}" target="_blank" rel="noopener">credential source ↗</a></small>`:''}</div>`).join('')}`:''}${c.evidence?.length?`<h3>Explicit evidence claims</h3>${c.evidence.map(x=>`<div class="evidence-claim"><b>${esc(x.claim_type.replaceAll('_',' '))}</b><span>${esc(x.claim_value)}</span><small>${sourceLink(x.source,x.source?.organization)} • verified ${esc(x.last_verified)}</small></div>`).join('')}`:''}<h3>Role profile</h3><div class="detail-grid">${Object.entries(d).filter(([k,v])=>v&&!['Market status','Salary context','O*NET role link','Wage source link','Evidence link'].includes(k)).map(([k,v])=>`<div class="detail"><h4>${esc(k)}</h4><p>${esc(v)}</p></div>`).join('')}</div><h3>How the ten college paths support this role</h3><div class="support-grid">${groups.map(([label,codes])=>{const ps=Object.entries(c.support).filter(([k,v])=>codes.includes(v)).map(([k])=>progByCode(k));return `<div class="support-box"><h4>${label}</h4>${ps.length?`<ul>${ps.map(p=>`<li><a href="#" onclick="event.preventDefault();openProgram('${p.code}')">${p.code} — ${esc(p.title)}</a></li>`).join('')}</ul>`:'<span class="subtle">None identified</span>'}</div>`}).join('')}</div><h3>Explore nearby possibilities</h3><p class="subtle">These controls intentionally broaden the search rather than treating the current role list as a closed universe.</p><div class="chipbar">${quick.map(x=>`<button class="chip" onclick="careerExcept('${esc(name).replace(/'/g,"\\'")}','${x}')">${x}</button>`).join('')}</div><div id="nearbyCareers"></div><div class="actions"><button class="btn ${state.savedCareers.includes(c.name)?'soft':''}" onclick="toggle(state.savedCareers,'${esc(c.name).replace(/'/g,"\\'")}');openCareer('${esc(c.name).replace(/'/g,"\\'")}')">★ ${state.savedCareers.includes(c.name)?'Saved':'Save career'}</button><button class="btn" onclick="state.progression.career='${esc(c.name).replace(/'/g,"\\'")}';save();closeModal();go('progression')">Career progression →</button>${d['O*NET role link']?`<a class="btn" target="_blank" href="${esc(d['O*NET role link'])}">O*NET ↗</a>`:''}</div></div></div></div>`}
function careerExcept(name,kind){const c=careerByName(name);let target=c.dims.slice(),contact=null,edu=null;if(kind==='More direct animal contact')contact='High';if(kind==='More research')target[8]=3;if(kind==='More fieldwork')target[3]=3;if(kind==='More conservation')target[6]=3;if(kind==='More behavior')target[0]=3;if(kind==='Less graduate school')edu='B.S.';const sim=D.careers.filter(x=>x.name!==name).map(x=>{let dist=0;for(let i=0;i<10;i++)dist+=(x.dims[i]-target[i])**2;if(contact&&x.directContact!==contact)dist+=4;if(edu&&x.educationBand.includes('Graduate'))dist+=5;return {x,dist}}).sort((a,b)=>a.dist-b.dist).slice(0,5).map(o=>o.x);document.getElementById('nearbyCareers').innerHTML=`<div class="grid cols-2" style="margin-top:12px">${sim.map(x=>`<div class="detail"><b>${esc(x.name)}</b><p>${esc(x.roleFocus)}</p><button class="btn small" onclick="openCareer('${esc(x.name).replace(/'/g,"\\'")}')">Open</button></div>`).join('')}</div>`}
function openProgram(code){const p=progByCode(code);const strong=D.careers.filter(c=>['S','SG'].includes(c.support[code])).slice(0,18);modalRoot.innerHTML=`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="kicker">${esc(p.school)} • ${esc(p.type)}</div><h2>${p.code}: ${esc(p.title)}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><p style="font-size:18px">${esc(p.fundamental)}</p><div class="detail-grid"><div class="detail"><h4>Scientific foundation</h4><ul>${p.scienceFoundation.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail"><h4>Animal / behavior / ecology content</h4><ul>${p.animalContent.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail"><h4>Experience profile</h4><p>${esc(p.experience)}</p></div><div class="detail"><h4>Undergraduate research</h4><p>${esc(p.research)}</p></div></div>${p.competencies?.length?`<h3>Competency preparation map</h3><div class="competency-map">${p.competencies.slice(0,18).map(x=>`<div class="competency-row"><span>${esc(x.name)}</span><div class="bar"><span style="width:${Math.round((x.strength/3)*100)}%"></span></div><b>${x.strength.toFixed(1)}</b></div>`).join('')}</div>`:''}<h3>Plausible four-year progression</h3><ol>${p.progression.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="notice"><b>What could plausibly be on the résumé:</b> ${esc(p.resume)}</div><div class="detail-grid" style="margin-top:14px"><div class="detail"><h4>Main advantages</h4><ul>${p.advantages.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail"><h4>Main tradeoffs</h4><ul>${p.tradeoffs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><p><b>Becomes especially attractive when:</b> ${esc(p.bestWhen)}</p><h3>Strongly supported careers</h3><div class="chipbar">${strong.map(c=>`<button class="chip" onclick="openCareer('${esc(c.name).replace(/'/g,"\\'")}')">${esc(c.name)}</button>`).join('')}</div><div class="actions"><button class="btn ${state.savedPrograms.includes(code)?'soft':''}" onclick="toggle(state.savedPrograms,'${code}');openProgram('${code}')">★ ${state.savedPrograms.includes(code)?'Saved':'Save path'}</button></div></div></div></div>`}
function closeModal(){modalRoot.innerHTML=''}

function openCareerCompare(){const cs=state.compareCareers.map(careerByName).filter(Boolean);modalRoot.innerHTML=`<div class="modal-back"><div class="modal"><div class="modal-head"><h2>Compare careers</h2><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body compare-table"><table><tr><th>Dimension</th>${cs.map(c=>`<th>${esc(c.name)}</th>`).join('')}</tr>${[['Domain',c=>c.domain?.name||c.category],['Role family',c=>c.roleFamily?.name||'—'],['Evidence',c=>evidenceLabel(c)],['Observed titles',c=>String(observedTitleCount(c))],['Recent postings',c=>String(currentPostingCount(c))],['Role focus',c=>c.roleFocus],['Animal contact',c=>c.directContact],['Education',c=>c.educationBand],['Work types',c=>c.workTags.join(', ')],['Observed posting pay',c=>postingSalaryText(c)||'—'],['Broad salary context',c=>c.details['Salary context']||'—']].map(([l,fn])=>`<tr><th>${l}</th>${cs.map(c=>`<td>${esc(fn(c))}</td>`).join('')}</tr>`).join('')}</table></div></div></div>`}
function openProgramCompare(){const ps=state.comparePrograms.map(progByCode).filter(Boolean);modalRoot.innerHTML=`<div class="modal-back"><div class="modal"><div class="modal-head"><h2>Compare college paths</h2><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body compare-table"><table><tr><th>Dimension</th>${ps.map(p=>`<th>${p.code}<br><small>${esc(p.title)}</small></th>`).join('')}</tr>${[['School',p=>p.school],['Program character',p=>p.type],['Fundamental focus',p=>p.fundamental],['Experience',p=>p.experience],['Research',p=>p.research],['Best when',p=>p.bestWhen],['Saved-career coverage',p=>programCareerCoverage(p,true)+' saved careers']].map(([l,fn])=>`<tr><th>${l}</th>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}</table></div></div></div>`}

function uncertaintyCards(){const unsure=[];[...D.topics,...D.activities,...D.relationships,...D.scienceQuestions].forEach(q=>{if(state.ratings[q.id]==='?')unsure.push(q.label)});const generic=D.unknownTests.filter(x=>{const s=x.unknown.toLowerCase();return unsure.some(u=>{const a=u.toLowerCase();return (s.includes('field')&&a.includes('field'))||(s.includes('animal care')&&(a.includes('care')||a.includes('husbandry')))||(s.includes('research')&&a.includes('research'))||(s.includes('rehab')&&a.includes('rehab'))||(s.includes('data')&&(a.includes('data')||a.includes('statistics')))||(s.includes('education')&&(a.includes('education')||a.includes('teach')))||(s.includes('zoo')&&a.includes('zoo'))})});return {unsure,generic}}
function saveSnapshot(){const tops=topThemes(5).map(t=>({label:t.label,score:t.score}));state.snapshots.unshift({date:new Date().toLocaleDateString(),themes:tops,savedCareers:[...state.savedCareers],savedPrograms:[...state.savedPrograms]});state.snapshots=state.snapshots.slice(0,12);save();renderDashboard()}
function renderDashboard(){const ts=themeScores().filter(x=>x.known||x.unknown).sort((a,b)=>b.score-a.score), rc=recommendedCareers(6),rp=recommendedPrograms(4),un=uncertaintyCards();app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">My exploration</div><h1>Current snapshot</h1><p>A living record—not a result. Save snapshots after meaningful experiences and see whether the pattern changes.</p></div><button class="btn primary" onclick="saveSnapshot()">Save snapshot</button></div><div class="dashboard-top"><div class="card"><h3>Current themes</h3>${ts.length?ts.map(t=>`<div class="theme-row"><small>${esc(t.label)}${t.unknown?` <span title="Uncertainty is useful">?${t.unknown}</span>`:''}</small><div class="bar"><span style="width:${Math.round(t.score*100)}%"></span></div></div>`).join(''):`<div class="empty">Complete any part of Guided Explore to start building a pattern.</div>`}</div><div class="card"><h3>Open questions</h3>${un.unsure.length?`<p class="subtle">Marked “not sure”:</p><ul>${un.unsure.slice(0,9).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p class="subtle">No “not sure” ratings yet. Uncertainty is welcome when experience is limited.</p>`}</div></div>
<div class="section-title"><div><h2>Careers worth looking at next</h2><p>Ordered from the current interest pattern. Open the career profile and react to the concrete work rather than relying on the name.</p></div></div><div class="grid cols-3">${rc.map(c=>careerCard(c,true)).join('')}</div>
<div class="section-title"><div><h2>College paths currently connecting well</h2><p>These reflect current interests; saved-career coverage becomes more useful after some career profiles have been explored.</p></div></div><div class="grid cols-2">${rp.map(p=>programCard(p,true)).join('')}</div>
<div class="section-title"><div><h2>Things to test in the real world</h2></div></div><div class="grid cols-2">${(un.generic.length?un.generic:D.unknownTests.slice(0,6)).map(x=>`<div class="card"><h3>${esc(x.unknown)}</h3><p>${esc(x.test)}</p></div>`).join('')}</div>
<div class="section-title"><div><h2>Saved</h2></div></div><div class="grid cols-2"><div class="card"><h3>Careers (${state.savedCareers.length})</h3>${state.savedCareers.length?`<div class="chipbar">${state.savedCareers.map(n=>`<button class="chip" onclick="openCareer('${esc(n).replace(/'/g,"\\'")}')">${esc(n)}</button>`).join('')}</div>`:'<p class="subtle">Save careers from the Career Explorer.</p>'}</div><div class="card"><h3>College paths (${state.savedPrograms.length})</h3>${state.savedPrograms.length?`<div class="chipbar">${state.savedPrograms.map(c=>`<button class="chip" onclick="openProgram('${c}')">${c} — ${esc(progByCode(c).title)}</button>`).join('')}</div>`:'<p class="subtle">Save paths from the College Path Explorer.</p>'}</div></div>
<div class="section-title"><div><h2>Snapshots over time</h2></div></div><div class="card">${state.snapshots.length?state.snapshots.map(s=>`<div class="snapshot"><b>${esc(s.date)}</b><div class="subtle">${s.themes.map(t=>`${esc(t.label)} ${Math.round(t.score*100)}%`).join(' • ')}</div><small>${s.savedCareers.length} saved careers • ${s.savedPrograms.length} saved paths</small></div>`).join(''):'<p class="subtle">Save a snapshot after a new experience, college visit, course, internship, or meaningful change in thinking.</p>'}<div class="actions"><button class="btn small" onclick="if(confirm('Reset all saved exploration data?')){state=blankState();save();renderDashboard()}">Reset local data</button></div></div></div>`}

function renderEvidence(){const S=D.dataSummary,tier=x=>S.sourceTierCounts?.[x]||0;const sourceCards=(D.sources||[]).sort((a,b)=>a.authority_tier.localeCompare(b.authority_tier)||a.organization.localeCompare(b.organization));const groups={};for(const d of D.domains||[]){groups[d.domain_id]=D.roleFamilies.filter(f=>f.domain_id===d.domain_id)}const marketBlock=S.marketSnapshotJobs?`<div class="section-title"><div><h2>AZA complete-board snapshot</h2><p>The complete public board is stored separately from the curated career map. Only human-reviewed, in-scope matches become career evidence.</p></div></div><div class="stats-grid market-stats"><div class="stat"><b>${S.marketSnapshotJobs}</b><span>board listings captured</span></div><div class="stat"><b>${S.marketJobsClassified}</b><span>scope-classified</span></div><div class="stat"><b>${S.marketJobsReviewed}</b><span>human-reviewed</span></div><div class="stat"><b>${S.marketJobsMatched}</b><span>accepted role matches</span></div><div class="stat"><b>${S.marketJobsPendingReview}</b><span>awaiting review</span></div></div>`:"";app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">Research database • snapshot ${esc(S.asOf)}</div><h1>Market & Evidence</h1><p>The site now separates canonical career concepts from the titles employers actually use. This page shows what is in the research database, where it came from, and where coverage is still incomplete.</p></div></div><div class="stats-grid"><div class="stat"><b>${S.canonicalRoles}</b><span>canonical roles / pathways</span></div><div class="stat"><b>${S.roleFamilies}</b><span>role families</span></div><div class="stat"><b>${S.searchAliases}</b><span>curated search aliases</span></div><div class="stat"><b>${S.observedTitles}</b><span>observed market titles</span></div><div class="stat"><b>${S.currentRecentPostings}</b><span>current/recent postings</span></div><div class="stat"><b>${S.explicitProgressionEdges}</b><span>explicit progression edges</span></div><div class="stat"><b>${S.sources}</b><span>registered sources</span></div><div class="stat"><b>${S.openReviewItems}</b><span>open research-review items</span></div></div>${marketBlock}<div class="notice" style="margin-top:18px"><b>The map is deliberately open-ended.</b> A role can exist even when no current posting is in this snapshot, and employers may use titles not yet observed here. The database records both what is verified and what still needs more evidence rather than treating the displayed list as the boundary of possible careers.</div><div class="section-title"><div><h2>How the data is organized</h2></div></div><div class="grid cols-3"><div class="card"><h3>1. Canonical role</h3><p>A stable concept used for exploration, such as Wildlife Biologist or Behavioral Husbandry Specialist.</p></div><div class="card"><h3>2. Real market observations</h3><p>Employer titles, job postings, staff directories, salary ranges, credentials and qualification standards are linked back to the canonical role.</p></div><div class="card"><h3>3. Evidence-backed connections</h3><p>College preparation and career progression can be explained through competencies, formal requirements and explicit progression edges.</p></div></div><div class="section-title"><div><h2>Career taxonomy</h2><p>${S.domains} domains contain ${S.roleFamilies} role families. Role families keep a growing title universe navigable without pretending each employer title is a separate profession.</p></div></div>${(D.domains||[]).map(d=>`<div class="card taxonomy-domain"><h3>${esc(d.name)} <span>${d.roleCount} roles</span></h3><p>${esc(d.description)}</p><div class="chipbar">${(groups[d.domain_id]||[]).map(f=>`<span class="chip static">${esc(f.name)} · ${f.role_count}</span>`).join('')}</div></div>`).join('')}<div class="section-title"><div><h2>Source hierarchy</h2><p>Different source types answer different questions. Current job postings are strongest for titles, duties and salary observations; federal/professional standards are stronger for qualifications and credentials.</p></div></div><div class="grid cols-3"><div class="card"><div class="kicker">Tier A • ${tier('A')} sources</div><h3>Official / authoritative</h3><p>Federal qualification standards, permits, agency staff directories and other primary institutional sources.</p></div><div class="card"><div class="kicker">Tier B • ${tier('B')} sources</div><h3>Professional organizations</h3><p>Organizations such as AZA, The Wildlife Society, NWRA and professional credential bodies.</p></div><div class="card"><div class="kicker">Tier C • ${tier('C')} sources</div><h3>Observed employers / postings</h3><p>Individual job postings and employer evidence used to validate market titles, duties, experience and pay.</p></div></div><div class="section-title"><div><h2>Registered sources</h2></div></div><div class="source-table"><div class="source-row source-head"><b>Tier</b><b>Organization</b><b>Use</b><b>Retrieved</b></div>${sourceCards.map(x=>`<div class="source-row"><span class="tier tier-${esc(x.authority_tier)}">${esc(x.authority_tier)}</span><span><b>${esc(x.organization)}</b><small>${esc(x.title)}</small></span><span>${esc(x.source_type.replaceAll('_',' '))}</span><span>${esc(x.retrieved_date)}<br>${sourceLink(x,'source')}</span></div>`).join('')}</div><div class="section-title"><div><h2>Coverage still being expanded</h2></div></div><div class="card"><p><b>${S.rolesWithPostingEvidence}/${S.canonicalRoles}</b> roles have a current/recent posting in this snapshot and <b>${S.rolesWithObservedTitles}/${S.canonicalRoles}</b> have at least one directly observed title. That is intentional transparency, not an implication that the remaining roles are invalid.</p><p>Next research priorities include deeper posting evidence for shelter behavior, sanctuary work, comparative cognition, conservation breeding/population management, and additional salary and progression observations.</p><div class="actions"><button class="btn primary" onclick="go('careers')">Explore the career map</button></div></div></div>`} 

function renderGlossary(){app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">Reference</div><h1>Working glossary</h1><p>These definitions clarify what terms represent in this exploration. Search here or use them while reviewing careers and programs.</p></div></div><input id="glossSearch" class="searchbox" style="max-width:520px;margin-bottom:18px" placeholder="Search terms and definitions…"><div class="glossary-grid" id="glossResults"></div></div>`;const upd=()=>{const q=document.getElementById('glossSearch').value.toLowerCase();document.getElementById('glossResults').innerHTML=D.glossary.filter(g=>(g.term+' '+g.definition).toLowerCase().includes(q)).map(g=>`<div class="term"><h3>${esc(g.term)}</h3><p>${esc(g.definition)}</p></div>`).join('')};document.getElementById('glossSearch').oninput=upd;upd()}
route();
